  "@planner.previous": "Предыдущие строки",
  "@planner.next": "Следующие строки",
  "@planner.limits": "Только два сохранённых файла и доступный MetadataCache. Кэш может обновляться с задержкой; его изменения отменяют план. Несохранённые правки, другие зависимости и смысловая полнота не проверены. Safe Apply & Undo отдельно проверяет источники, диапазон, разрешение ссылок, известные зависимости, редакторы и согласие перед записью с журналом.",

  "@ux.expandFragment": "Раскрыть весь фрагмент",
