  "@relationship.privacy": "После подтверждения полные исходные тексты, включая frontmatter, будут переданы провайдеру. Возможна оплата по его тарифу.",
  "@relationship.fullInput": "Встраивания и другие заметки не загружаются. Имена файлов передаются только внутри текста. Veynrel не сохраняет анализ; правила хранения данных провайдера действуют отдельно.",
  "@relationship.payload": "Адрес и точное тело запроса",
