  "@topology.select": "Выберите заметку на карте или в поиске, чтобы увидеть её связи.",
  "@topology.incoming-notes": "Ссылающиеся заметки ({n})",
  "@topology.outgoing-notes": "Адресаты ссылок ({n})",
  "@topology.legend": "Размер: число разрешённых связей · пустой круг: нет связей · пунктир: связи неизвестны · кольцо: связующая заметка. У выбранной заметки: пунктирные входящие, сплошные исходящие, утолщённые взаимные связи.",
  "@tools.local": "Локальная структура",
  "@tools.openTagTaxonomy": "Таксономия тегов",
  "@tools.openTagTaxonomy.description": "Локальный инвентарь и правила категорий. Рекомендации модели — только после подтверждения запроса. Заметки не изменяются.",
  "@tagRec.title": "Рекомендации тегов",
  "@tagRec.scope": "Используется только сохранённый подтверждённый профиль, а не черновик ниже. Сначала выполните локальное сканирование. Выбор заметки не запускает анализ. Рекомендации требуют отдельного подтверждения отправки модели; Markdown не изменяется.",
  "@tagRec.select": "Выбрать заметку по полному пути",
  "@tagRec.noSelection": "Заметка не выбрана.",
  "@tagRec.analyze": "Рекомендовать теги",
  "@tagRec.cancel": "Отменить анализ",
  "@tagRec.confirm": "Подтвердить и отправить",
  "@tagRec.dismiss": "Отклонить результат",
  "@tagRec.volume": "Полный сохранённый текст: {characters} ед. UTF-16. Наблюдаемых тегов: {tags}; исключено заметок: {excluded}. Тело запроса: {bytes} байт UTF-8.",
  "@tagRec.privacy": "После подтверждения провайдер получит весь исходный Markdown выбранной заметки (включая frontmatter и написанные в ней имена, пути и ссылки), подтверждённые правила и весь ограниченный инвентарь тегов подходящих заметок. Содержимое встраиваний не загружается. Возможна плата. Проверьте адрес и точное тело запроса. Veynrel не сохраняет анализ; правила хранения провайдера действуют отдельно.",
  "@tagRec.limits": "Пределы v1: {characters} ед. UTF-16 текста, {tags} тегов, {categories} категорий, {requestBytes} байт UTF-8 запроса. При превышении анализ целиком отклоняется; частичный словарь не отправляется.",
  "@tagRec.provisional": "Предварительные выводы модели. Проверены схема, цитаты и формальные правила, но не правильность смысловой классификации. Рекомендации не применяются.",
  "@tagRec.quote": "Цитата: проверено точное уникальное вхождение в исходный текст.",
  "@tagRec.existing": "Рекомендуемые существующие теги",
  "@tagRec.proposed": "Возможные новые теги",
  "@tagRec.none": "Категории без рекомендации",
  "@tagRec.empty": "Нет предложений в этом разделе.",
  "@tagRec.outcome.recommend": "Модель предлагает классификацию",
  "@tagRec.outcome.none": "Подходящих тегов для этой категории не обнаружено в переданных данных",
  "@tagRec.outcome.insufficient_context": "Недостаточно контекста для рекомендации",
  "@tagRec.domain": "Область, относительно которой сделан вывод",
  "@tagRec.prerequisites": "Необходимые предварительные знания",
  "@tagRec.newScope": "Предложение для указанной категории, а не новый сохранённый тег или правило. Модель сравнивает его с ближайшими наблюдавшимися тегами. Будущее повторное использование неизвестно; исключённые заметки и задержки кэша могут скрывать уже существующий тег.",
  "@tagRec.coverage": "Проанализированы только сохранённый текст выбранной заметки, подтверждённый профиль и снимок MetadataCache подходящих заметок. Полнота и свежесть самого кэша не гарантируются. Правки в редакторе, встраивания, исключённые заметки и будущая полезность новых тегов неизвестны. Отсутствие рекомендации не доказывает отсутствие подходящего тега во всём vault.",
  "@tagRec.stage.idle": "Выберите заметку; анализ запускается только кнопкой.",
  "@tagRec.stage.preparing": "Подготовка полного запроса для просмотра…",
  "@tagRec.stage.consent": "Данные не отправлены. Проверьте запрос и подтвердите отправку.",
