  "@health.confirm-all": "This resets Veynrel Health findings and scan history only. Existing files will be moved to Health recovery backups first.",
  "@health.confirm-history": "This resets Veynrel Health scan history only. Findings will be preserved. Existing history will be moved to a Health recovery backup first.",
