  "@health.cancel": "Cancel",
  "@health.confirm": "Back up and reset",
  "@health.loading": "Loading Health…",
  "@health.note-unavailable": "This note is no longer available. Scan again to refresh Health.",
  "@health.command": "Open Veynrel Health",
  "@health.open-failed": "Veynrel Health could not be opened. Try again.",
  "@map_sys": "You are a knowledge-base analyst. Analyze each note briefly and in a structured way.\nReply with a STRICTLY valid JSON array, no Markdown, no comments, no surrounding text.\n\nFor each file return an object with this structure:\n{\n  \"path\": \"path from the request\",\n  \"topics\": [\"topic1\", \"topic2\"],\n  \"keyIdeas\": \"1-2 sentences about the core idea of the note\",\n  \"entities\": [\"name/concept/technology\"],\n  \"quality\": \"draft\" | \"developed\" | \"polished\",\n  \"suggestedTags\": [\"#tag1\", \"#tag2\"],\n  \"suggestedLinks\": [\"likely related notes by meaning\"]\n}\n\nIf the note is empty, contains only links, or is a stub — quality: \"draft\", keyIdeas: \"empty stub note\", topics: [], entities: [], suggestedTags: [].\nIMPORTANT: Never repeat phrases. Each field is unique information. Reply strictly with JSON.",
  "@cluster_sys": "You are an Obsidian knowledge architect. You will receive note summaries (JSON).\nYour task is to identify 3-7 thematic CLUSTERS and propose a structure.\n\nReply with STRICTLY valid JSON, no Markdown:\n{\n  \"clusters\": [\n    {\n      \"name\": \"Cluster name\",\n      \"description\": \"What this cluster is about, 1-2 sentences\",\n      \"filePaths\": [\"path1\", \"path2\"],\n      \"suggestedMOC\": \"Name of the suggested MOC note\"\n    }\n  ]\n}",
  "@final_sys": "You are a PKM and Obsidian expert. The input is a list of the user's note clusters.\nWrite a structured report in Markdown, in English:\n\n## 🔍 Global insights\n3-5 observations about the knowledge structure (thematic skews, gaps, strengths).\n\n## 🎯 Action plan\n5-7 concrete reorganization steps (numbered list). Each step = one action.\n\n## ⚠️ Problem areas\nWhat needs attention (orphans, duplicates, drafts).\n\nBe specific, reference cluster names. Do not include code.",
  "@map_user": "Analyze these notes:\n{payload}\n\nReturn a JSON array with one object per file ({n} total).",
  "@cluster_user": "Here are the note summaries:\n{data}\n\nIdentify the clusters.",
  "@merge_user": "Here are intermediate clusters. Merge semantically close ones and return 3-7 final clusters:\n{data}",
  "@final_user": "Knowledge base clusters:\n{clusters}\n\nOverall statistics:\n- Total notes: {total}\n- Orphans (no links): {orphans}\n- Drafts: {draft}\n- Developed: {dev}\n- Polished: {pol}\n\nWrite the report.",
  "@single_user": "Path: {path}\nCurrent tags: {tags}\nOutgoing links: {out} · Incoming: {inn}\n\nContent:\n{content}",
  "@audit_prompt": "Analyze the structure of this Obsidian vault.\n\nOVERALL STATISTICS:\n- Notes: {total}\n- With tags: {withTags}\n- Without links: {orphans}\n- State: {state}\n\nFILE LIST (Format: Name | Path | Tags | Links):\n{snapshot}\n\nTASK:\n1. Identify 3-5 thematic clusters.\n2. Give 5 concrete reorganization steps.\n3. Suggest 3-5 MOC note names.\nReply briefly and structurally in English.",
  "@dash_report": "---\ntype: audit-dashboard\ndate: {iso}\n---\n# 🚀 Vault audit dashboard\n\n> [!abstract] Quick summary\n> - **Total files:** {total}\n> - **Connectivity:** {conn}%\n> - **Status:** {status}\n\n---\n\n## 🤖 AI recommendations\n{advice}\n\n---\n\n## 📂 Architecture (Top folders)\n> [!info] Distribution\n{folders}\n\n## 🏷️ Tag cloud\n> [!quote] Main branches\n> {tags}\n\n---\n## 🔗 Isolated notes\n> [!warning] Orphans found: {orphans}\n> Linking them to a MOC is recommended.\n",
  "@folder_line": "> - **{name}**: {n} files",
  "@deep_cluster": "### 📚 {name}\n*{desc}*\n\n**Files:** {count} · **Suggested MOC:** `{moc}`\n\n**Files:**\n{files}{more}",
  "@deep_report": "---\ntype: deep-audit-report\ndate: {iso}\nduration: {duration}\nfiles_analyzed: {processed}\nfiles_failed: {failed}\n---\n\n# 🔬 Deep vault audit\n\n> [!abstract] Summary\n> - **Files analyzed:** {processed} of {total}\n> - **Failed to process:** {failed}\n> - **Clusters found:** {nclusters}\n> - **Duration:** {duration}\n\n---\n\n## 🧠 Thematic clusters\n\n{clustersMd}\n\n---\n\n{insights}\n\n---\n\n{actionPlan}\n\n---\n\n> [!tip] What's next?\n> 1. Create the MOC notes suggested above.\n> 2. Link the files in each cluster via backlinks.\n> 3. Run batch processing to add the recommended tags.\n",
  "@deep_canvas_center": "# 🔬 Deep Audit\n{date}\n\n**{n}** files\n**{c}** clusters",
  "@canvas_stats": "## 📈 Statistics\n- Files: {total}\n- Orphans: {orphans}",
  "@canvas_advice": "## 💡 AI advice\n{advice}",
  "@canvas_folders": "## 📂 Folder structure\n{folders}",
  "@batch_report": "# AI Batch Report\n\n📊 **Result**\n- Succeeded: {ok}\n- Errors: {err}\n- Backup: `{backup}/`\n",
  "@batch_errors": "\n## ⚠️ Errors\n{list}\n",
  "@flashcards_prompt": "You are a flashcard generator for Veynrel Recall in Obsidian. You are given the text of a note. Create flashcards for its key ideas.\n\nFORMAT — MOST IMPORTANT:\nEach card is EXACTLY ONE line of the form: question text::answer text\nThe \"::\" separator sits between the question and the answer ON THE SAME LINE. Left of \"::\" is the question text itself, right of it is the answer text itself. Label words such as \"Question\", \"Answer\", \"Вопрос\", \"Ответ\" are FORBIDDEN.\n\nEXAMPLES OF CORRECT CARDS (exactly like this):\nWhat is encapsulation::Hiding an object's internal implementation behind a public interface\nWhy use a database index::It speeds up lookups by avoiding full table scans\nHow does a thread differ from a process::Threads share the process memory, processes are isolated\n\nWRONG EXAMPLE (never do this — question and answer split across lines with labels):\nQuestion::What is encapsulation\nAnswer::Hiding the internal implementation\n\nREQUIREMENTS:\n- 3-7 cards depending on the note's size, covering the key ideas.\n- Keep answers short: 1-2 sentences.\n- Write all cards in the language of the note. ONE language throughout, no mixed-language insertions.\n\nFORBIDDEN:\n- Splitting a question and its answer onto separate lines.\n- Numbering, list bullets, leading dashes.\n- Markdown: code blocks, headings, bold/italics.\n- Intros or comments (\"Here are your cards:\" etc.).\n- Blank lines between cards.\nReturn ONLY the card lines.",
  "@moc_note": "---\ntype: moc\ndate: {iso}\n---\n\n# {title}\n\n{desc}\n\n## Notes ({n})\n\n{links}\n",
  "@moc_desc_sys": "You are an Obsidian knowledge-base assistant. Write a short description of a note cluster's topic: 1-2 sentences, to the point. Return ONLY the description text — no explanations, quotes or headings. Reply in English.",
  "@moc_desc_user": "Cluster topic: {name}\n\nCluster files:\n{files}\n\nWrite 1-2 sentences about what unites these notes.",
  "@atomize_prompt": "You are a Zettelkasten assistant in Obsidian. You are given the text of a note. Extract its ATOMIC ideas — self-contained thoughts, each deserving its own note.\n\nRESPONSE FORMAT — STRICTLY valid JSON, no Markdown wrappers, no comments, no surrounding text:\n{\"atoms\": [{\"title\": \"the gist of the idea in one short phrase\", \"body\": \"a fuller write-up of that single idea, 2-6 sentences\"}]}\n\nRULES:\n- Each atom is EXACTLY ONE idea: the title captures the gist, the body elaborates only on it.\n- title — a short phrase without Markdown and without the characters \\ / : * ? \" < > | # ^ [ ].\n- body — coherent, self-contained text that makes sense without the source note. Markdown is allowed in the body.\n- 2-8 atoms; do not split artificially just to increase the count.\n- If the note is already atomic (a single idea) or there is nothing to split — return {\"atoms\": []}.\n- Write in English.\nRespond with JSON ONLY.",
  "@atom_note": "---\ntype: atom\ndate: {iso}\n---\n\n# {title}\n\n{body}\n",
